begin;
select plan(7);
insert into auth.users (id, email) values ('00000000-0000-0000-0000-000000000041', 'deliverable-test@example.com');
insert into public.profiles (id, email, display_name, global_role, status) values ('00000000-0000-0000-0000-000000000041', 'deliverable-test@example.com', 'Deliverable Test', 'ADMIN', 'ACTIVE');
insert into public.projects (id, code, name, created_by, updated_by) values ('10000000-0000-0000-0000-000000000041', 'DELIVERABLE', 'Deliverable Test', '00000000-0000-0000-0000-000000000041', '00000000-0000-0000-0000-000000000041');
insert into public.workstreams (id, project_id, name, sort_order, created_by, updated_by) values ('20000000-0000-0000-0000-000000000041', '10000000-0000-0000-0000-000000000041', 'Main', 1, '00000000-0000-0000-0000-000000000041', '00000000-0000-0000-0000-000000000041');
insert into public.tasks (id, project_id, workstream_id, title, created_by, updated_by) values ('50000000-0000-0000-0000-000000000041', '10000000-0000-0000-0000-000000000041', '20000000-0000-0000-0000-000000000041', 'Deliverable Task', '00000000-0000-0000-0000-000000000041', '00000000-0000-0000-0000-000000000041');
insert into public.deliverables (id, project_id, task_id, title, created_by, updated_by) values ('70000000-0000-0000-0000-000000000041', '10000000-0000-0000-0000-000000000041', '50000000-0000-0000-0000-000000000041', 'Final Report', '00000000-0000-0000-0000-000000000041', '00000000-0000-0000-0000-000000000041');
set local role authenticated;
set local request.jwt.claim.sub = '00000000-0000-0000-0000-000000000041';
select lives_ok($$select public.submit_deliverable_version('70000000-0000-0000-0000-000000000041', 'https://example.com/v1', 'first')$$, 'A version can be submitted atomically');
select is((select current_version from public.deliverables), 1, 'Current version increments');
select is((select status::text from public.deliverables), 'SUBMITTED', 'Submission changes status');
select lives_ok($$select public.review_deliverable_version((select id from public.deliverable_versions limit 1), 'CHANGES_REQUESTED', '보완 필요')$$, 'A version can be reviewed');
select is((select status::text from public.deliverables), 'CHANGES_REQUESTED', 'Review decision changes status');
select is((select feedback from public.deliverable_reviews), '보완 필요', 'Review history is retained');
select throws_ok($$select public.submit_deliverable_version('70000000-0000-0000-0000-000000000041', 'ftp://example.com/v2', '')$$, 'P0001', 'Deliverable URL은 HTTP 또는 HTTPS여야 합니다.', 'Invalid version URL is rejected');
select * from finish();
rollback;
